	/* The following assumes that the variable is */
	/* represented by a single integer */

	err=MPI_T_cvar_read(handle,val);
	if (err!=MPI_SUCCESS) return err;

	err=MPI_T_cvar_handle_free(&handle);
	return err;
}

#include <stdio.h>
